#include "Music/SampledGuitar.h"
#include "Audio/SampleVoices.h"
#include <iostream>
int main(){auto dir=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("wingman-sfz-"+juce::Uuid().toString());dir.createDirectory();int checks=0;auto check=[&](bool b){++checks;if(!b)throw std::runtime_error("SFZ check "+std::to_string(checks));};
try{auto wav=dir.getChildFile("sample.wav");juce::AudioBuffer<float> data(2,4410);for(int i=0;i<4410;++i){data.setSample(0,i,.2f);data.setSample(1,i,.1f);}juce::WavAudioFormat format;auto stream=wav.createOutputStream();std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(stream.release(),44100,2,24,{},0));check(writer&&writer->writeFromAudioSampleBuffer(data,0,4410));writer.reset();
 auto sfz=dir.getChildFile("test.sfz");sfz.replaceWithText("<group> sample=sample.wav pitch_keycenter=60 ampeg_release=0.05\n<region> lokey=40 hikey=88 lovel=1 hivel=127 seq_length=2 seq_position=1 volume=-6\n<region> lokey=40 hikey=88 lovel=1 hivel=127 seq_length=2 seq_position=2\n");auto lib=wingman::SampledGuitar::load(sfz);check(lib.zones.size()==2);check(lib.bytes==2*4410*sizeof(float));wingman::GuitarSettings settings;settings.bars=1;
 std::vector<wingman::NoteEvent> notes; // NoteEvent field ordering below is explicit.
 notes.clear();wingman::NoteEvent n;n.note=60;n.velocity=100;n.beat=0;n.duration=.1;n.channel=1;notes.push_back(n);n.beat=1;notes.push_back(n);
 for(double rate:{44100.,48000.}){auto out=lib.render(notes,settings,120,rate);auto at=static_cast<std::size_t>(.01*rate),second=static_cast<std::size_t>(.51*rate);check(out.channels[0][second]>out.channels[0][at]*1.9f);check(out.channels[0][at]>out.channels[1][at]*1.9f);check(out.channels[0][static_cast<std::size_t>(.2*rate)]==0);check(out.channels[0][static_cast<std::size_t>(.49*rate)]==0);}
 sfz.replaceWithText("<region> sample=missing.wav");bool failed=false;try{wingman::SampledGuitar::load(sfz);}catch(...){failed=true;}check(failed);
 sfz.replaceWithText("<region> sample=sample.wav unsupported=1");failed=false;try{wingman::SampledGuitar::load(sfz);}catch(...){failed=true;}check(failed);
 sfz.replaceWithText("<region> sample=sample.wav lovel=110 hivel=127");lib=wingman::SampledGuitar::load(sfz);failed=false;try{lib.render(notes,settings,120,48000);}catch(...){failed=true;}check(failed);
 failed=false;try{wingman::SampledGuitar::load(sfz,[](double){return false;});}catch(...){failed=true;}check(failed);
 sfz.replaceWithText("<region> sample=sample.wav key=60 lovel=1 hivel=64 volume=-12\n<region> sample=sample.wav key=60 lovel=65 hivel=127\n");lib=wingman::SampledGuitar::load(sfz);auto soft=notes;for(auto& note:soft)note.velocity=40;auto quiet=lib.render(soft,settings,120,48000);auto loud=lib.render(notes,settings,120,48000);check(loud.channels[0][480]>quiet.channels[0][480]*5);
 sfz.replaceWithText("<region> sample=sample.wav key=60 sw_last=29\n");lib=wingman::SampledGuitar::load(sfz);failed=false;try{lib.render(notes,settings,120,48000);}catch(...){failed=true;}check(failed);settings.technique=wingman::GuitarTechnique::PalmMute;check(!lib.render(notes,settings,120,48000).channels[0].empty());settings.technique=wingman::GuitarTechnique::Strumming;
 sfz.replaceWithText("<region> sample=sample.wav key=60\n<region> sample=sample.wav key=60 trigger=release ampeg_release=0.1\n");lib=wingman::SampledGuitar::load(sfz);auto released=lib.render(notes,settings,120,48000);check(released.channels[0][4800]>0);failed=false;try{lib.render(notes,settings,120,48000,1,[](double){return false;});}catch(...){failed=true;}check(failed);
 wingman::SampleVoices voices;voices.bind(&lib,1);juce::AudioBuffer<float> block(2,512);block.clear();juce::MidiBuffer events;events.addEvent(juce::MidiMessage::noteOn(1,60,static_cast<juce::uint8>(100)),100);events.addEvent(juce::MidiMessage::noteOff(1,60),300);voices.render(block,events,48000,24,1);check(block.getMagnitude(0,100)==0);check(block.getSample(0,250)>block.getSample(1,250)*1.9f);check(voices.activeVoices()>0);wingman::NoteEvent aligned;aligned.note=60;aligned.channel=1;aligned.velocity=100;aligned.beat=100.0/48000*2;aligned.duration=200.0/48000*2;auto alignedWav=lib.render({aligned},settings,120,48000);for(int i=0;i<512;++i)check(std::abs(block.getSample(0,i)-alignedWav.channels[0][static_cast<std::size_t>(i)])<.00001f);events.clear();for(int i=0;i<30;++i){block.clear();voices.render(block,events,48000,24,1);}check(voices.activeVoices()==0&&block.getMagnitude(0,512)==0);
 sfz.replaceWithText("<region> sample=sample.wav key=60 pan=100 ampeg_attack=0.01 ampeg_decay=0.01 ampeg_sustain=25 ampeg_release=0.02");lib=wingman::SampledGuitar::load(sfz);check(lib.uniqueSamples==1&&lib.zones[0].pan==1&&lib.zones[0].sustain==.25);auto panned=lib.render(notes,settings,120,48000);check(panned.channels[0][240]==0&&panned.channels[1][240]>.02f);check(panned.channels[1][240]>panned.channels[1][1440]*1.9f);
 for(auto opcode:{"pan=101","ampeg_attack=-1","ampeg_sustain=101"}){sfz.replaceWithText("<region> sample=sample.wav "+juce::String(opcode));bool rejected=false;try{wingman::SampledGuitar::load(sfz);}catch(...){rejected=true;}check(rejected);}
 dir.deleteRecursively();std::cout<<checks<<" sampled guitar checks passed\n";return 0;
}catch(const std::exception& e){dir.deleteRecursively();std::cerr<<e.what()<<'\n';return 1;}}
